import { useMemo, type CSSProperties, type ReactNode } from 'react';
import './ascii-glimmer-panel.css';

export interface AsciiGlimmerPanelProps {
  /** The real content, shown above the decorative grid. */
  children: ReactNode;
  columns?: number;
  rows?: number;
  /** Change this value to run the wave again. */
  playKey?: number | string;
  className?: string;
}

const CHARS = '.:-=+*~';

/**
 * A decorative grid of characters lights up in one diagonal wave and then
 * rests. The grid is hidden from assistive technology; the real content sits
 * on a solid panel above it, so contrast never depends on the effect.
 */
export function AsciiGlimmerPanel({
  children,
  columns = 32,
  rows = 9,
  playKey = 0,
  className = '',
}: AsciiGlimmerPanelProps) {
  const grid = useMemo(
    () =>
      Array.from({ length: rows }, (_, r) =>
        Array.from(
          { length: columns },
          (_, c) => CHARS[(r * 7 + c * 3 + ((r * c) % 5)) % CHARS.length]
        )
      ),
    [rows, columns]
  );
  return (
    <div className={`mg-ascii ${className}`}>
      <div
        key={playKey}
        className='mg-ascii__grid'
        aria-hidden='true'
        style={{ gridTemplateColumns: `repeat(${columns}, 1fr)` }}
      >
        {grid.flatMap((row, r) =>
          row.map((ch, c) => (
            <span
              key={`${r}-${c}`}
              style={{ '--mg-delay': `${(r + c) * 22}ms` } as CSSProperties}
            >
              {ch}
            </span>
          ))
        )}
      </div>
      <div className='mg-ascii__content'>{children}</div>
    </div>
  );
}

.mg-ascii {
  position: relative;
  display: grid;
  place-items: center;
  overflow: hidden;
  padding: 24px 16px;
  border-radius: 14px;
  background: var(--mg-raised, #262626);
}

.mg-ascii__grid {
  position: absolute;
  inset: 8px;
  display: grid;
  align-content: space-between;
  color: #8f8f8f;
  font:
    12px/1.2 ui-monospace,
    SFMono-Regular,
    Menlo,
    monospace;
  text-align: center;
  user-select: none;
}

.mg-ascii__grid span {
  animation: mg-ascii-glim 520ms ease-out both;
  animation-delay: var(--mg-delay);
}

.mg-ascii__content {
  position: relative;
  padding: 14px 18px;
  border-radius: 10px;
  background: var(--mg-raised, #262626);
  box-shadow: 0 0 0 1px #474747;
  color: #ffffff;
  text-align: center;
}

@keyframes mg-ascii-glim {
  0% {
    color: #8f8f8f;
  }
  35% {
    color: var(--mg-accent-text, #8aa8ff);
    text-shadow: 0 0 6px rgba(100, 138, 255, 0.6);
  }
  100% {
    color: #8f8f8f;
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-ascii__grid span {
    animation: none;
  }
}
